frappe.ui.form.on('Contract Billing Schedule', {
    form_render: function (frm, cdt, cdn) {
        console.log("🔹 form_render triggered for Contract Billing Schedule row");

        let row = locals[cdt][cdn];
        console.log("📄 Current Row Data:", row);

        // ✅ Get the specific grid row instance
        let grid_row = frm.fields_dict['billing_schedule'].grid.get_row(cdn);

        if (!row.invoice_link) {
            console.log("⚠️ No invoice_link found for this row.");
            grid_row.get_field('html_field').$wrapper.html('<p>Please select an Invoice first.</p>');
            return;
        }

        console.log(`🔗 Fetching Invoice Doc: ${row.invoice_link}`);

        frappe.db.get_doc('Invoice', row.invoice_link)
            .then(invoice => {
                console.log("✅ Invoice fetched successfully:", invoice);

                if (invoice.invoice_payment_term && invoice.invoice_payment_term.length) {
                    console.log(`📊 Found ${invoice.invoice_payment_term.length} payment term rows`);

                    let html = `
                        <table class="table table-bordered table-sm">
                            <thead>
                                <tr>
                                    <th>Portion</th>
                                    <th>Portion Amount</th>
                                    <th>Due Date</th>
                                    <th>Received Amount</th>
                                    <th>Amount Received Date</th>
                                    <th>Outstanding as per Portion</th>
                                    <th>Payment ID</th>
                                </tr>
                            </thead>
                            <tbody>
                    `;
                    const formatDate = (dateStr) => {
                        if (!dateStr) return '';
                        const d = new Date(dateStr);
                        const day = String(d.getDate()).padStart(2, '0');
                        const month = String(d.getMonth() + 1).padStart(2, '0');
                        const year = d.getFullYear();
                        return `${day}-${month}-${year}`;
                    };

                    invoice.invoice_payment_term.forEach((term, idx) => {
                        console.log(`➡️ Row ${idx + 1}:`, term);
                        html += `
                            <tr>
                                <td>${term.portion || ''}</td>
                                <td>${term.portion_amount || ''}</td>
                                <td>${formatDate(term.due_date) || ''}</td>
                                <td>${term.amount_received || ''}</td>
                                <td>${formatDate(term.amount_received_date) || ''}</td>
                                <td>${term.outstanding_as_per_portion || ''}</td>
                                <td>${term.payment_id || ''}</td>
                            </tr>
                        `;
                    });

                    html += `</tbody></table>`;

                    console.log("🧱 Final HTML generated:", html);

                    // ✅ Correctly render inside grid dialog field
                    grid_row.get_field('invoice_information').$wrapper.html(html);
                    console.log("🎯 HTML rendered successfully inside grid row dialog.");
                } else {
                    console.log("ℹ️ No payment terms found for this invoice.");
                    grid_row.get_field('invoice_information').$wrapper.html('<p>No Payment Terms found for this Invoice.</p>');
                }
            })
            .catch(err => {
                console.error("❌ Error fetching Invoice:", err);
                frappe.msgprint(__('Could not fetch the linked Invoice details.'));
            });
    },

});

frappe.listview_settings['CRM Organization'] = {
	onload: function(listview) {
		// Add Download Template button with icon
		listview.page.add_inner_button(
			 `<i class="fa fa-download" style="margin-right: 4px; vertical-align: middle;"></i>` + __("Download Template"),
			function() {
				frappe.call({
					method: "crm.fcrm.doctype.crm_organization.crm_organization.download_excel_template",
					callback: (r) => {
						if (r.message) {
							window.open(r.message, "_blank");
						}
					},
					error: (err) => {
						console.error("Template download failed:", err);
						frappe.msgprint(__("Template download failed. Check console."));
					}
				});
			}
		);

		// Add Customer Upload button as primary with icon
		const upload_btn = listview.page.add_inner_button(
			`<i class="fa fa-upload" style="margin-right: 4px; vertical-align: middle;"></i>` + __("Customer Upload"),
			function() {
				const d = new frappe.ui.Dialog({
					title: __("Excel Import (CRM Organization)"),
					fields: [
						{
							fieldname: "excel_file",
							label: __("Excel File (.xlsx/.xls)"),
							fieldtype: "Attach",
							reqd: 1
						}
					],
					primary_action_label: __("Upload & Import"),
					primary_action(values) {
						const file_url = values.excel_file;
						if (!file_url) return;

						const ext = (file_url.split(".").pop() || "").toLowerCase();
						if (!["xlsx", "xls"].includes(ext)) {
							frappe.msgprint(__("Upload only Excel (.xlsx/.xls)"));
							return;
						}

						d.set_primary_action(__("Importing..."), null);

						frappe.call({
							method: "crm.fcrm.doctype.crm_organization.crm_organization.import_excel_crm_organization",
							args: { file_url },
							callback: (r) => {
								d.hide();
								frappe.msgprint(r.message || __("Done"));
								listview.refresh();
							},
							error: (err) => {
								console.error("Excel import failed:", err);
								frappe.msgprint(__("Import failed. Check Error logs."));
							},
							always: () => {
								d.set_primary_action(__("Upload & Import"), () => d.primary_action(values));
							}
						});
					}
				});

				d.show();
			}
		);

		// Style the Customer Upload button as primary
		upload_btn.removeClass('btn-default').addClass('btn-primary');
	}
};

