frappe.ui.form.on('Opportunity', {
    refresh(frm) {
        console.log("TESTINGS")
        // Only show when document is saved
        if (frm.is_new()) return;

        // Use setTimeout to ensure buttons aren't overwritten by standard UI render
        setTimeout(() => {
            // Remove existing to avoid duplicates on manual refresh
            frm.remove_custom_button('Download Products Template', 'Products');
            frm.remove_custom_button('Import Products', 'Products');

            // Add Download Template
            frm.add_custom_button(
                __('Download Products Template'), 
                () => {
                    frappe.call({
                        method: "crm.api.opportunity_products.download_products_template",
                        callback: r => {
                            if (r.message) window.open(r.message, "_blank");
                        }
                    });
                }, 
                __("Products")
            );

            // Add Import Button
            frm.add_custom_button(
                __('Import Products'), 
                () => {
                    const d = new frappe.ui.Dialog({
                        title: __("Import Products"),
                        fields: [
                            {
                                fieldname: "excel_file",
                                label: __("Excel File (.xlsx)"),
                                fieldtype: "Attach",
                                reqd: 1
                            }
                        ],
                        primary_action_label: __("Import"),
                        primary_action(values) {
                            frappe.call({
                                method: "crm.api.opportunity_products.import_products",
                                args: {
                                    opportunity: frm.doc.name,
                                    file_url: values.excel_file
                                },
                                callback: r => {
                                    d.hide();
                                    frm.reload_doc();
                                    frappe.show_alert(r.message || __("Imported"), 5);
                                }
                            });
                        }
                    });
                    d.show();
                }, 
                __("Products")
            );
        }, 10);
    }
});

