frappe.ui.form.on('CRM Quotation', {
    onload: function(frm) {
        // Fetch exchange rate if the field is empty
        if (!frm.doc.conversion_rate) {
            fetchExchangeRate(frm);
        }
    },

    // Triggered when INR Price Rate changes
    price_rate: function(frm) {
        updateCalculations(frm);
    },

    // Triggered when INR Amount changes
    amount: function(frm) {
        updateCalculations(frm);
    },

    // Triggered if user manually overrides the conversion rate
    conversion_rate: function(frm) {
        updateCalculations(frm);
    }
});

// ================= HELPER FUNCTIONS =================

/**
 * Fetches the latest USD to INR exchange rate from the system.
 * Based on your logic, it calculates the rate to convert INR -> USD.
 */
function fetchExchangeRate(frm) {
    const today = frappe.datetime.nowdate();

    frappe.db.get_list('Currency Exchange', {
        filters: {
            from_currency: "USD",
            to_currency: "INR",
            for_selling: 1,
            date: ['<=', today]
        },
        fields: ['exchange_rate'],
        order_by: 'date desc',
        limit: 1
    }).then(r => {
        if (r && r.length) {
            // If 1 USD = 83 INR, then conversion_rate (INR to USD) is 1 / 83
            const rate = flt(1 / r[0].exchange_rate, 9);
            frm.set_value('conversion_rate', rate);
            updateCalculations(frm);
        } else {
            // Fallback rate if no record found
            console.log("No Currency Exchange record found. Using fallback.");
            frm.set_value('conversion_rate', 0.012); 
        }
    });
}

/**
 * Performs the math: INR Value * conversion_rate = USD Value
 */
function updateCalculations(frm) {
    const rate = flt(frm.doc.conversion_rate, 9);

    // 1. Convert Amount (INR) to Total USD
    if (frm.doc.amount) {
        const total_usd = flt(frm.doc.amount) * rate;
        // Only update if value actually changed to prevent "Not Saved" loops
        if (flt(frm.doc.total_usd, 2) !== flt(total_usd, 2)) {
            frm.set_value('total_usd', flt(total_usd, 2));
        }
    }

    // 2. Optional: If you have a specific USD field for price_rate, 
    // you can add it here. Your JSON only showed 'total_usd'.

    console.log(`Calculation updated using Rate: ${rate}`);
}

