frappe.ui.form.on('Serial No', {
    start_date: function(frm) {
        frm.trigger('calculate_period');
    },
    expiry_date: function(frm) {
        frm.trigger('calculate_period');
    },
    calculate_period: function(frm) {
        if (frm.doc.start_date && frm.doc.expiry_date) {
            const start = frappe.datetime.str_to_obj(frm.doc.start_date);
            const end = frappe.datetime.str_to_obj(frm.doc.expiry_date);
            const diff = frappe.datetime.get_day_diff(end, start);

            if (diff >= 0) {
                frm.set_value('warranty_period_in_days', diff);
            } else {
                frappe.msgprint(__('Expiry Date should be after Start Date'));
                frm.set_value('warranty_period_in_days', 0);
            }
        } else {
            frm.set_value('warranty_period_in_days', 0); // Reset if dates are not provided
        }
    }
});

frappe.ui.form.on('Serial No', {
    expiry_date: function(frm) {
        frm.trigger('calculate_days_left');
    },
    calculate_days_left: function(frm) {
        if (frm.doc.expiry_date) {
            const today = frappe.datetime.str_to_obj(frappe.datetime.get_today());
            const expiry = frappe.datetime.str_to_obj(frm.doc.expiry_date);
            const days_left = frappe.datetime.get_day_diff(expiry, today);

            if (days_left >= 0) {
                frm.set_value('days_left', days_left);
            } else {
                frm.msgprint(__('The expiry date has already passed.'));
                frm.set_value('days_left', 0);
            }
        } else {
            frm.set_value('days_left', 0); // Reset if expiry_date is not provided
        }
    }
});

frappe.ui.form.on('Serial No', {
    refresh: function (frm) {
        frm.trigger('set_status');
    },
    type: function (frm) {
        frm.trigger('set_status');
    },
    expiry_date: function (frm) {
        frm.trigger('set_status');
    },
    start_date: function (frm) {
        frm.trigger('set_status');
    },
    set_status: function (frm) {
        const type = frm.doc.type;
        const expiry_date = frm.doc.expiry_date ? frappe.datetime.str_to_obj(frm.doc.expiry_date) : null;
        const current_date = new Date();

        if (type === 'Warranty') {
            if (expiry_date && expiry_date > current_date) {
                frm.set_value('status', 'In Warranty');
            } else {
                frm.set_value('status', 'Out Warranty');
            }
        } else if (type === 'AMC') {
            if (expiry_date && expiry_date > current_date) {
                frm.set_value('status', 'AMC Active');
            } else {
                frm.set_value('status', 'AMC Expired');
            }
        } else if (type === 'N/A') {
            frm.set_value('status', 'N/A');
        } else {
            frm.set_value('status', '');
        }
    }
});

frappe.ui.form.on('CRM Organization', {
    region: function (frm) {
        if (frm.doc.region) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Region Master',
                    name: frm.doc.region, // Selected Region Master
                },
                callback: function (response) {
                    const regionData = response.message;
                    if (regionData && regionData.branches) {
                        // Extract Branch IDs from the child table
                        const branchList = regionData.branches.map(row => row.branch_id);
                        frm.set_query('branch', function () {
                            return {
                                filters: {
                                    name: ['in', branchList], // Filter Region Branches
                                },
                            };
                        });
                    } else {
                        frappe.msgprint(__('No branches found for the selected region.'));
                        frm.set_query('branch', function () {
                            return {}; // Clear branch query
                        });
                    }
                },
                error: function () {
                    frappe.msgprint(__('Unable to fetch branches. Please try again.'));
                },
            });
        } else {
            // Clear branch filter if no region is selected
            frm.set_query('branch', function () {
                return {};
            });
        }
    },
});

