// ✅ Helper function to safely update fields
function safe_set_value(frm, field, value) {
    if (frm.doc[field] !== value) {
        frm.set_value(field, value);
    }
}

// ✅ Main logic for CRM Deal
frappe.ui.form.on('CRM Deal', {
    customer_name(frm) {
        // Reset both address fields only if they actually differ
        safe_set_value(frm, 'customer_address', '');
        safe_set_value(frm, 'shipping_address', '');

        // Set query for Billing addresses
        frm.set_query('customer_address', () => ({
            filters: [
                ['Dynamic Link', 'link_doctype', '=', 'CRM Organization'],
                ['Dynamic Link', 'link_name', '=', frm.doc.customer],
                ['disabled', '=', 0]
            ]
        }));

        // Set query for Shipping addresses
        frm.set_query('shipping_address', () => ({
            filters: [
                ['Dynamic Link', 'link_doctype', '=', 'CRM Organization'],
                ['Dynamic Link', 'link_name', '=', frm.doc.customer],
                ['disabled', '=', 0]
            ]
        }));

        // Auto-select first Billing address
        frappe.db.get_list('Address', {
            filters: [
                ['Dynamic Link', 'link_doctype', '=', 'CRM Organization'],
                ['Dynamic Link', 'link_name', '=', frm.doc.customer],
                ['disabled', '=', 0]
            ],
            fields: ['name'],
            limit: 1
        }).then(result => {
            if (result.length) {
                safe_set_value(frm, 'customer_address', result[0].name);
                frm.trigger('customer_address'); // Render address HTML
            }
        });

        // Auto-select first Shipping address
        frappe.db.get_list('Address', {
            filters: [
                ['Dynamic Link', 'link_doctype', '=', 'CRM Organization'],
                ['Dynamic Link', 'link_name', '=', frm.doc.customer],
                ['disabled', '=', 0]
            ],
            fields: ['name'],
            limit: 1
        }).then(result => {
            if (result.length) {
                safe_set_value(frm, 'shipping_address', result[0].name);
                frm.trigger('shipping_address'); // Render address HTML
            }
        });
    },

    customer_address(frm) {
        render_address_html(frm, 'customer_address', 'address_html');
    },

    shipping_address(frm) {
        render_address_html(frm, 'shipping_address', 'shipping_address_html');
    },

    onload(frm) {
        if (frm.doc.customer_address) {
            frm.trigger('customer_address');
        }
        if (frm.doc.shipping_address) {
            frm.trigger('shipping_address');
        }
    }
});

// ✅ Address rendering helper
function render_address_html(frm, address_fieldname, html_fieldname) {
    const address_name = frm.doc[address_fieldname];
    if (address_name) {
        frappe.db.get_doc('Address', address_name).then(address => {
            const html = `
                <div style="background-color: #f9f9f9; border: 1px solid #ddd; padding: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.05); font-size: 14px; line-height: 1.6; position: relative;">
                    <div style="position: absolute; top: 10px; right: 10px; cursor: pointer;" 
                         title="Edit Address"
                         onclick="frappe.set_route('Form', 'Address', '${address.name}')">
                        ✎
                    </div>
                    ${address.address_line1 || ''}<br>
                    ${address.address_line2 || ''}<br>
                    ${address.city || ''}, ${address.state || ''} - ${address.pincode || ''}<br>
                    ${address.country || ''}<br>
                    ${address.phone || ''}<br>${address.email_id || ''}
                </div>
            `;
            frm.fields_dict[html_fieldname].$wrapper.html(html);
        });
    } else {
        frm.fields_dict[html_fieldname].$wrapper.html('');
    }
}

