function calculate_total_hp(frm) {
    let total = 0;

    // Loop through all rows in child table
    frm.doc.product_details.forEach(row => {
        if (row.hp) {
            let hp_val = parseFloat(row.hp);
            if (!isNaN(hp_val)) {
                total += hp_val;
            }
        }
    });

    // Set the calculated total to parent field
    frm.set_value("total_hp", total);
}

