/*──────────────────────────────────────────────────────────────────────────
  Helper: open a new Address, pre‑linked to this organization
──────────────────────────────────────────────────────────────────────────*/
function open_new_address(frm) {
	frappe.route_options = {
		address_title: frm.doc.organization_name || frm.doc.name,
		links: [{
			link_doctype: 'CRM Organization',
			link_name: frm.doc.name
		}]
	};
	frappe.new_doc('Address');
}

/*──────────────────────────────────────────────────────────────────────────
  Helper: if an Address was just saved, render its HTML block
──────────────────────────────────────────────────────────────────────────*/
async function render_address_if_any(frm) {
	const latest = localStorage.getItem('latest_created_address_for_crm_org');
	if (!latest) return;

	// ensure we render only once
	localStorage.removeItem('latest_created_address_for_crm_org');

	try {
		const adr = await frappe.db.get_doc('Address', latest);

		const html = `
			<div style="border:1px solid #d1d8dd;border-radius:8px;padding:16px;background:#f9fafb;position:relative">
				<!-- edit icon -->
				<div style="position:absolute;top:10px;right:10px;cursor:pointer"
				     title="Edit Address"
				     onclick="frappe.set_route('Form','Address','${adr.name}')">✎</div>

				<div style="font-size:14px;line-height:1.6;color:#4a4a4a">
					${adr.address_line1 || ''}<br>
					${adr.address_line2 ? adr.address_line2 + '<br>' : ''}
					${adr.city || ''}${adr.state ? ', ' + adr.state : ''} ${adr.pincode || ''}<br>
					${adr.country || ''}<br>
					${adr.email_id ? '<strong>Email:</strong> ' + adr.email_id + '<br>' : ''}
					${adr.phone ? '<strong>Phone:</strong> ' + adr.phone : ''}
				</div>
			</div>`;

		// store HTML value in the field (so it’s saved with the doc)
		frm.set_value('address_html', html);

		// immediately show it in the form
		frm.fields_dict.address_html.$wrapper.html(html);
	} catch (e) {
		console.error('Could not load address', e);
		frm.fields_dict.address_html.$wrapper.empty();
	}
}

