frappe.ui.form.on('CRM Deal', {
    customer_name: async function (frm) {

        if (!frm.doc.customer_name) {
            frm.set_query('project', () => ({}));
            return;
        }

        const org = await frappe.db.get_doc('CRM Organization', frm.doc.customer);

        const project_list = (org.custom_project_info || [])
            .map(row => row.project)
            .filter(p => !!p);         

        // 3) Apply a dynamic query on the Project field
        frm.set_query('project', () => {
            return {
                filters: [
                    ['Project', 'name', 'in', project_list]  // only these projects
                ]
            };
        });

        // 4) (Optional) auto‑select if there’s exactly one project
        if (project_list.length === 1) {
            frm.set_value('project', project_list[0]);
        }
    },

    // // Also re‑apply filter while opening an already‑saved doc
    // onload: function (frm) {
    //     if (frm.doc.customer_name) {
    //         frm.trigger('customer_name');
