    },
    warranty_expiry_date: function(frm) {
        set_duplicate_trigger_date(frm);
    }
});

function set_duplicate_trigger_date(frm) {
    let amc = frm.doc.amc_expiry_date;
    let warranty = frm.doc.warranty_expiry_date;

    if (amc) {
        frm.set_value('duplicate_trigger_date', frappe.datetime.add_months(amc, -1));
    } else if (warranty) {
        frm.set_value('duplicate_trigger_date', frappe.datetime.add_months(warranty, -1));
    } else {
        frm.set_value('duplicate_trigger_date', null);
    }
}






