function shouldFetchNewRate(frm) {
    // No rate at all - fetch one
    if (!frm.doc.conversion_rate) return true;

    // No date field - skip date check
    if (!frm.fields_dict.conversion_date) return false;

    // Rate is stale (older than 24 hours)
    const rateDate = new Date(frm.doc.conversion_date);
    return (new Date() - rateDate) > 86400000;
}

async function fetchExchangeRate(frm) {
    const API_ENDPOINTS = [
        'https://api.exchangerate-api.com/v4/latest/INR',
        'https://api.frankfurter.app/latest?from=INR&to=USD',
        'https://open.er-api.com/v6/latest/INR'
    ];

    for (const endpoint of API_ENDPOINTS) {
        try {
            const response = await fetch(endpoint);
            if (!response.ok) continue;

            const data = await response.json();
            const rate = data.rates?.USD;

            if (rate) {
                applyNewRate(frm, rate);
                return;
            }
        } catch (error) {
            console.error('Exchange API error:', error);
            continue;
        }
    }

    // All APIs failed - use fallback
    applyNewRate(frm, 0.012); // Default fallback rate
    frappe.msgprint({
        title: __('Warning'),
        message: __('Using fallback exchange rate'),
        indicator: 'orange'
    });
}

function applyNewRate(frm, rate) {
    // Set primary conversion rate
    frm.set_value('conversion_rate', rate);

    // Update date if field exists
    if (frm.fields_dict.conversion_date) {
        frm.set_value('conversion_date', frappe.datetime.nowdate());
    }

    // Update inverse rate if field exists
    if (frm.fields_dict.conversion_rate_inverse) {
        frm.set_value('conversion_rate_inverse', (1 / rate).toFixed(4));
    }

    // Update all calculations
    updateCalculations(frm);
}

function updateCalculations(frm) {
    // Get values with proper fallbacks
    const price_inr = parseFloat(frm.doc.price_rate || 0);
    const amount_inr = parseFloat(frm.doc.amount || 0);
    const rate = parseFloat(frm.doc.conversion_rate || 0.012); // Fallback to 0.012 if no rate

    // Calculate USD values
    const price_usd = price_inr * rate;
    const total_usd = amount_inr * rate;

    // Update fields
    frm.set_value('price_rate_usd', price_usd.toFixed(2));
    frm.set_value('total_usd', total_usd.toFixed(2));

    // Optional: Show rate info in console for debugging
    console.log(`Exchange rate applied: 1 INR = ${rate} USD`);
}


