    },
    end_date: function(frm) {
        calculate_amc_year(frm);
    }
});

function calculate_amc_year(frm) {
    if (frm.doc.start_date && frm.doc.end_date) {
        const start = frappe.datetime.str_to_obj(frm.doc.start_date);
        const end = frappe.datetime.str_to_obj(frm.doc.end_date);

        let amc_years = 0;
        let anniversary = new Date(start);

        // Count full anniversaries <= end_date
        while (anniversary <= end) {
            amc_years += 1;
            anniversary.setFullYear(anniversary.getFullYear() + 1);
        }

        frm.set_value('amc_year', amc_years);
    }
}

frappe.ui.form.on('CRM Quotation', {
    refresh(frm) {
        const doc_status = frm.doc.status;
        const zone = frm.doc.zone;

        if (doc_status === "Approval Pending") {
            if (zone && zone !== "Green") {
                let approverChain = "";

                if (zone === "Yellow") {
                    approverChain = "Yellow Zone Approvers";
                } else if (zone === "Orange") {
                    approverChain = "Yellow and Orange Zone Approvers";
                } else if (zone === "Red") {
                    approverChain = "Yellow, Orange, and Red Zone Approvers";
                }

                const zoneColor = {
                    "Yellow": "hsl(47, 87%, 88%)",
                    "Orange": "hsl(15, 87.2%, 88.2%)",
                    "Red": "hsla(0, 50%, 90%)"
                }[zone] || "transparent";

                const HtmlMessage = `<div style="
                    padding: 20px 40px;
                    border-radius: 10px;
                    border: 2px solid ${zone};
                    background: ${zoneColor};
                ">
                    ✨ As per Rate, Vertical, & HP, Quote falls under <b>${zone} Zone</b>.<br>
                    It requires Approval from <b>${approverChain}</b>.
                </div>`;

                frm.set_df_property("quote_message", "options", HtmlMessage);
            } else {
                // Green zone or no zone: no approval needed
                frm.set_df_property("quote_message", "options", `<div style="
                    padding: 20px 40px;
                    border-radius: 10px;
                    border: 2px solid #ccc;
                    background: #f8f8f8;
                ">
                    ✅ This quote falls under <b>Green Zone</b>. No approval is required.
                </div>`);
            }
        } else {
            // Other statuses like Approved, PO Pending, Quote Won, etc.
            const message = doc_status === "Approved" ? "✅ Congratulations! Your Quote is ready to send to customer" :
                doc_status === "PO Pending" ? "📄 Attach Customer PO in the Attachment tab" :
                doc_status === "Quote Won" ? "<b>🎉 Congratulations!</b> Quote has been won.<b>AMC</b> is Awarded.<br> Please proceed with <b>AMC Contract</b> Creation." :
                `${doc_status}`;

            frm.set_df_property("quote_message", "options", `<div style="
                padding: 20px 40px;
                border-radius: 10px;
                border: 2px solid green;
                background: hsl(110, 90%, 90%);
            ">${message}</div>`);
        }
    }
});

