// Function to calculate total HP from all rows and set in parent
function calculate_hp(frm) {
    let total = 0;

    // Make sure child table exists
    if (frm.doc.product_details && frm.doc.product_details.length>0) {
        frm.doc.product_details.forEach(row => {
            if (row.hp) {
                const val = parseFloat(row.hp);
                if (!isNaN(val)) {
                    total += val;
                }
            }
        });
    }

    // Set total in parent field "hp"
    frm.set_value("hp", total);
}

