                             : warranty_from_register;
            } else if (warranty_from_register) {
                final_date = warranty_from_register;
            } else if (warranty_from_commision) {
                final_date = warranty_from_commision;
            }

            if (final_date) {
                frm.set_value("warranty_expiry_date", frappe.datetime.obj_to_str(final_date));
            }
        }
    },




});

frappe.ui.form.on("CRM Quotation", {
    refresh(frm) {
        console.log("CRM Quotation refresh triggered");

        // Loop through workflow buttons
        frm.page.wrapper.find(".btn[data-action]").each(function() {
            let $btn = $(this);
            let action = $btn.attr("data-action");
            console.log("Found button action:", action);

            // Only handle Approve/Reject
            if (action === "Approve" || action === "Reject") {
                console.log("Attaching dialog to action:", action);
                $btn.off("click"); // remove default handler
                $btn.on("click", function() {
                    console.log("Button clicked for action:", action);

                    // Show remarks dialog
                    let d = new frappe.ui.Dialog({
                        title: __('Enter Remarks'),
                        fields: [
                            {
                                fieldname: 'remarks',
                                label: __('Remarks'),
                                fieldtype: 'Small Text',
                                reqd: 1
                            }
                        ],
                        primary_action_label: __('Submit'),
                        primary_action: function(values) {
                            console.log("Dialog submitted with values:", values);

                            // Set remarks field
                            frm.set_value('remarks', values.remarks);

                            // Save form and then execute workflow
                            frm.save().then(() => {
                                console.log("Form saved, applying workflow action:", action);
                                frappe.workflow.apply_workflow_action(frm.doc, action).then(() => {
                                    console.log("Workflow action applied:", action);
                                    frm.reload_doc();
                                    d.hide();
                                });
                            });
                        }
                    });
                    d.show();
                });
            }
        });
    }
});

